const {createTracker}=require('./dist/playtest.js');
const dist=path.join(__dirname,'dist'),PROFILE='hexrota-profile-v2',browserName=process.env.HEXROTA_BROWSER||'chromium';
assert(['chromium','webkit'].includes(browserName),'supported native browser');
const output=process.env.HEXROTA_IDLE_SCREENSHOT_DIR||path.join(__dirname,'test-results','idle-hints-'+browserName);
const baselineRef=process.env.HEXROTA_IDLE_BASELINE_REF||'616c66389d1aca7c225b56641f27bc901e5a9012';
fs.mkdirSync(output,{recursive:true});
const reference={window:{},performance};vm.createContext(reference);
for(const file of ['engine.js','commands.js','levels.js','tutorials.js','variants-data.js','attempts.js'])vm.runInContext(fs.readFileSync(path.join(dist,file),'utf8'),reference,{filename:file});
const R=reference.window,Engine=R.HexMatch,catalog=R.HexAttempts.createCatalog(R.HEX_LEVELS,R.HEX_VARIANTS,Engine);
function campaignSeed(){
 const saved=fresh(2),metadata={attemptVersion:1,levelId:1,variantId:'v1',levelDataVersion:R.HEX_VARIANTS.levelDataVersion,attemptId:'a-1-7-0041abca',attemptSerial:7};
 saved.boards[2]=plain(new Engine(catalog.resolveLevel(1,'v1',R.HEX_VARIANTS.levelDataVersion)).snapshot());
 saved.attempts={2:metadata};saved.attemptStats={2:{attemptId:metadata.attemptId,attemptNumber:1,started:true,terminalEvent:null,hintsUsed:0,cascades:0}};
 saved.variantSelection.serial=7;saved.variantSelection.counts[1]=1;saved.variantSelection.recent[1]=['v1'];return saved;
}
function nearLoss(){const saved=campaignSeed(),g=new Engine(catalog.resolveLevel(1,'v1',R.HEX_VARIANTS.levelDataVersion)),route=findLoss(g);for(const pair of route.slice(0,-1))assert(g.swap(...pair).ok);saved.boards[2]=plain(g.snapshot());return {saved,pair:route.at(-1)};}
function optedIn(){const tracker=createTracker({now:()=>Date.now(),monotonic:()=>performance.now()});tracker.setEnabled(true);return tracker.snapshot();}

// App integration still constructs its production controller/view. This wrapper
// supplies that controller's existing clock dependencies and observes callbacks;
// it never supplies eligibility, a suggested pair or a gameplay command.
const policyInstrumentation=`\n;(()=>{
 const native=window.HexIdleHints,clone=value=>JSON.parse(JSON.stringify(value));
 window.HexIdleHints=Object.freeze({...native,create(options){
  let time=0,serial=0;const tasks=new Map(),retired=[],shows=[],hides=[],choices=[],reads=[];
  const schedule=(fn,delay)=>{const id=++serial;tasks.set(id,{id,at:time+Math.max(0,Number(delay)||0),fn});return id;};
  const clear=id=>{const task=tasks.get(id);if(task){tasks.delete(id);retired.push(task);}};
  const read=()=>{const value=options.read();reads.push({at:time,value:clone(value)});return value;};
  const controller=native.create({...options,now:()=>time,setTimeout:schedule,clearTimeout:clear,read,
   choosePair(...args){const pair=options.choosePair(...args);choices.push({at:time,pair:clone(pair),context:clone(args)});return pair;},
   onShow(payload){shows.push({at:time,payload:clone(payload)});return options.onShow(payload);},
   onHide(payload){hides.push({at:time,payload:clone(payload)});return options.onHide(payload);}
  });
  const harness={advance(delta){if(!Number.isFinite(delta)||delta<0)throw Error('invalid test delta');const end=time+delta;let count=0;while(true){const next=[...tasks.values()].filter(row=>row.at<=end).sort((a,b)=>a.at-b.at||a.id-b.id)[0];if(!next)break;if(++count>1000)throw Error('idle clock loop');tasks.delete(next.id);time=next.at;next.fn();}time=end;return this.capture();},
   capture(){return clone({now:time,shows,hides,choices,lastRead:reads.at(-1)||null,pending:[...tasks.values()].map(({id,at})=>({id,at})),retired:retired.length});},
   deliverRetired(){const rows=retired.splice(0);for(const row of rows)row.fn();return rows.length;}
  };
  window.__idleBrowser=harness;return controller;
 }});
})();\n`;
const viewInstrumentation=`\n;(()=>{
 const native=window.HexIdleHintView;
 window.HexIdleHintView=Object.freeze({...native,create(options){const view=native.create(options);return Object.freeze({...view,show(payload){const result=view.show(payload);if(window.__idleFreezeVisual)for(const animation of options.board.querySelector('.idle-hint-layer')?.getAnimations({subtree:true})||[]){animation.pause();animation.currentTime=0;}return result;}});}});
})();\n`;
const mime={'.html':'text/html','.js':'application/javascript','.css':'text/css','.json':'application/json','.svg':'image/svg+xml','.webp':'image/webp','.png':'image/png','.jpg':'image/jpeg','.webmanifest':'application/manifest+json'};
const baselineFiles=new Map(['app.js','index.html','style.css'].map(file=>[file,execFileSync('git',['show',baselineRef+':dist/'+file],{cwd:__dirname})]));
const requests=[],results=[],errors=[],externalRequests=[];let browser,url,failure=null,currentCase=null;
const server=http.createServer((req,res)=>{
 let pathname;try{pathname=decodeURIComponent(new URL(req.url,'http://local').pathname);}catch(_){res.writeHead(400).end();return;}
 const baseline=pathname.startsWith('/baseline/');if(baseline)pathname=pathname.slice('/baseline'.length);
 const file=path.resolve(dist,'.'+(pathname==='/'?'/index.html':pathname));if(!file.startsWith(dist+path.sep)){res.writeHead(403).end();return;}
 requests.push({path:new URL(req.url,'http://local').pathname,baseline});
 const send=bytes=>{let body=bytes;if(!baseline&&path.basename(file)==='idle-hints.js')body=Buffer.concat([bytes,Buffer.from(policyInstrumentation)]);if(!baseline&&path.basename(file)==='idle-hint-view.js')body=Buffer.concat([bytes,Buffer.from(viewInstrumentation)]);if(!baseline&&path.basename(file)==='app.js'&&process.env.HEXROTA_IDLE_DEBUG)body=Buffer.from(bytes.toString().replace('function idleHintFacts(){','function idleHintFacts(){window.__idleFactsDebug=()=>({state:appState.snapshot(),domain:inputDomainView(),active,tutorialCount,screen:document.body.dataset.screen,hidden:document.hidden,idleUnfocused,idlePageHidden,selected,pointer:!!pointer,assistanceMode:!!assistanceMode,pendingAssistance:!!pendingAssistance,hint:appHintPending(),pendingStage,pendingRestart:!!pendingRestart,pendingRescueProvider:!!pendingRescueProvider,pendingRescueReceipt:!!pendingRescueReceipt,pendingLifeProvider:!!pendingLifeProvider,pendingLifeReceipt:!!pendingLifeReceipt,coachHidden:$("tutorial-coach").hidden,feedback:!!guideFeedback(),invalidPresentation:!!invalidPresentation,fullResetPending});'));res.writeHead(200,{'content-type':mime[path.extname(file)]||'application/octet-stream','cache-control':'no-store'}).end(body);};
 if(baseline&&baselineFiles.has(path.basename(file))){send(baselineFiles.get(path.basename(file)));return;}
 fs.readFile(file,(error,bytes)=>{if(error){res.writeHead(404).end();return;}send(bytes);});
});
async function open({size={width:390,height:844},saved=campaignSeed(),motion='full',baseline=false,enterGame=true,freezeVisual=true}={}){
 const context=await browser.newContext({viewport:size,deviceScaleFactor:1,isMobile:true,hasTouch:true,reducedMotion:motion==='reduce'?'reduce':'no-preference',serviceWorkers:'block'});
 await context.addInitScript(({saved,energy,observations,motion,freezeVisual})=>{
  if(location.protocol!=='http:')return;
  window.__idleFreezeVisual=freezeVisual;
  if(!localStorage.getItem('hexrota-profile-v2')&&!localStorage.getItem('hexrota-match-v5')){saved.preferences={...saved.preferences,motion};localStorage.setItem('hexrota-match-v5',JSON.stringify(saved));localStorage.setItem('hexrota-lives-v1',JSON.stringify(energy));localStorage.setItem('hexrota-playtest-v1',JSON.stringify(observations));}
  const NativeWorker=window.Worker;window.__idleWorkerRequests=[];
  function ObservedWorker(script,options){window.__idleWorkerRequests.push(new URL(script,location.href).pathname);return new NativeWorker(script,options);}
  ObservedWorker.prototype=NativeWorker.prototype;Object.setPrototypeOf(ObservedWorker,NativeWorker);window.Worker=ObservedWorker;
 },{saved,energy:lifePool(5),observations:optedIn(),motion,freezeVisual});
 const page=await context.newPage();page.on('pageerror',error=>errors.push({case:currentCase,message:error.message}));
 context.on('request',request=>{if(!request.url().startsWith(url)&&!request.url().startsWith('blob:')&&!request.url().startsWith('data:'))externalRequests.push(request.url());});
 try{await page.goto(url+(baseline?'baseline/':''),{waitUntil:'domcontentloaded'});await page.waitForFunction(()=>document.body.dataset.screen==='home');if(!baseline)await page.waitForFunction(()=>!!window.__idleBrowser);if(enterGame)await enter(page);return {context,page,close:()=>context.close()};}catch(error){await context.close();throw error;}
}
async function enter(page){await page.locator('#home-play').tap();if(await page.locator('#pregame-dialog').evaluate(node=>node.open))await page.locator('#pregame-start').tap();await page.waitForFunction(()=>document.body.dataset.screen==='game'&&document.getElementById('board').getAttribute('aria-busy')==='false');await settled(page);}
async function settled(page){await page.locator('#board').evaluate(async board=>{const jobs=[];for(let node=board;node;node=node.parentElement)for(const a of node.getAnimations())if(a.effect?.target===node&&a.playState==='running'&&a.effect.getTiming().iterations!==Infinity)jobs.push(a.finished.catch(()=>{}));await Promise.all(jobs);await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));});}
async function advance(page,delta){return page.evaluate(delta=>window.__idleBrowser.advance(delta),delta);}
async function captured(page){return page.evaluate(()=>window.__idleBrowser.capture());}
async function appearanceCount(page){return (await captured(page)).shows.length;}
async function cycleCount(page){return (await captured(page)).shows.filter(row=>row.payload.repeated===false).length;}
async function stores(page){return page.evaluate(()=>Object.fromEntries(['hexrota-profile-v2','hexrota-events-v1','hexrota-playtest-v1','hexrota-match-v5','hexrota-lives-v1'].map(key=>[key,localStorage.getItem(key)])));}
async function profile(page){return page.evaluate(key=>JSON.parse(localStorage.getItem(key)),PROFILE);}
const board=p=>p.game.boards[p.game.current];
async function point(page,index){const box=await page.locator('#board [data-index="'+index+'"] .floor-shape').boundingBox();assert(box,'native hit target '+index);return {x:box.x+box.width/2,y:box.y+box.height/2};}
async function tapTile(page,index){const p=await point(page,index);await page.touchscreen.tap(p.x,p.y);}
async function touchPair(page,pair){for(const index of pair)await tapTile(page,index);await page.waitForFunction(()=>document.getElementById('board').getAttribute('aria-busy')==='false');await settled(page);}
async function legalMove(page){return page.evaluate(()=>{const p=JSON.parse(localStorage.getItem('hexrota-profile-v2')),index=p.game.current,m=p.game.attempts[index],catalog=HexAttempts.createCatalog(HEX_LEVELS,HEX_VARIANTS,HexMatch),level=catalog.resolveLevel(m.levelId,m.variantId,m.levelDataVersion),game=p.game.boards[index].rulesVersion==='assisted-v1'?new HexAssistedGame(level,{attemptId:m.attemptId},p.game.boards[index]):new HexMatch(level,p.game.boards[index]);return game.legalMoves().find(pair=>{const copy=game.clone();return copy.swap(...pair).ok&&copy.status==='playing';})||game.legalMoves()[0];});}
async function invalidMove(page){return page.evaluate(()=>{const p=JSON.parse(localStorage.getItem('hexrota-profile-v2')),index=p.game.current,m=p.game.attempts[index],level=HexAttempts.createCatalog(HEX_LEVELS,HEX_VARIANTS,HexMatch).resolveLevel(m.levelId,m.variantId,m.levelDataVersion),game=new HexMatch(level,p.game.boards[index]);return game.topology.pairs.find(pair=>!game.clone().swap(...pair).ok);});}
async function validCue(page){
 const seen=await captured(page),payload=seen.shows.at(-1)?.payload,p=await profile(page);assert(payload?.pair?.length===2,'actual controller publishes one pair: '+JSON.stringify({...seen,debug:await page.evaluate(()=>window.__idleFactsDebug?.())}));
 const metadata=p.game.attempts[p.game.current],level=catalog.resolveLevel(metadata.levelId,metadata.variantId,metadata.levelDataVersion),snapshot=board(p),game=snapshot.rulesVersion==='assisted-v1'?new R.HexAssistedGame(level,{attemptId:metadata.attemptId,limits:snapshot.limits},snapshot):new Engine(level,snapshot);
 assert(game.adjacent(...payload.pair),'cue pair is adjacent in canonical topology');assert(game.legalMoves().some(pair=>pair.slice().sort((a,b)=>a-b).join(',')===payload.pair.slice().sort((a,b)=>a-b).join(',')),'cue is legal in the actual canonical board: '+JSON.stringify({payload,metadata,values:snapshot.values,legal:game.legalMoves(),seen:seen.shows,pending:seen.pending,lastRead:seen.lastRead,now:seen.now}));
 assert.equal(payload.attemptId,metadata.attemptId);assert.equal(payload.duration,900);assert.equal(typeof payload.repeated,'boolean','every actual appearance identifies its distinct cycle or repetition');assert.equal(await page.locator('.idle-hint-layer').count(),1);assert.equal(await page.locator('.idle-hint-pair').count(),2,'exactly two suggested pair clones; extra matching-source emphasis is separate');
 assert.equal(await page.locator('.swap-pair,.swap-layer .swap-stone').count(),0,'a cue creates no real swap presentation');
 assert.deepEqual(await page.evaluate(()=>window.__idleWorkerRequests),[],'passive guidance never starts the manual solver worker');return payload;
}
async function passiveEqual(page,before,label){assert.deepEqual(await stores(page),before,label+' retains full canonical revision/profile, game, attempt, RNG, rewards, economy, life and both event stores byte for byte');assert.deepEqual(await page.evaluate(()=>window.__idleWorkerRequests),[],'passive display never creates a worker');}
async function geometry(page){return page.evaluate(()=>{const rect=node=>node.getBoundingClientRect().toJSON(),board=document.getElementById('board');return {board:rect(board),tiles:[...board.children].filter(n=>n.hasAttribute('data-index')).map(node=>({index:Number(node.dataset.index),tile:rect(node),floor:rect(node.querySelector('.floor-shape')),gem:rect(node.querySelector('.gem')),transform:node.getAttribute('transform'),tabindex:node.getAttribute('tabindex')})),controls:[...document.querySelectorAll('#game-home,#reset,#open-inventory,#pause,#game-settings')].filter(node=>!node.hidden).map(node=>({id:node.id,rect:rect(node)}))};});}
function stable(before,after,label){for(const key of ['x','y','width','height'])assert(Math.abs(before[key]-after[key])<=1,label+' '+key+' '+before[key]+' → '+after[key]);}
function sameBoard(before,after,label){stable(before.board,after.board,label+' board');for(let i=0;i<before.tiles.length;i++){assert.equal(after.tiles[i].index,before.tiles[i].index);stable(before.tiles[i].floor,after.tiles[i].floor,label+' floor '+i);stable(before.tiles[i].gem,after.tiles[i].gem,label+' real gem '+i);assert.equal(after.tiles[i].transform,before.tiles[i].transform);assert.equal(after.tiles[i].tabindex,before.tiles[i].tabindex);}}
function fitsGeometry(g,size){for(const item of [{id:'board',rect:g.board},...g.controls]){const b=item.rect;assert(b.width>0&&b.height>0,item.id+' visible');assert(b.x>=-1&&b.y>=-1&&b.x+b.width<=size.width+1&&b.y+b.height<=size.height+1,item.id+' fits '+JSON.stringify({b,size}));}}
async function hitTargets(page){assert.equal(await page.evaluate(()=>[...document.querySelectorAll('#board [data-index]')].every(node=>{const r=node.querySelector('.floor-shape').getBoundingClientRect();return document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)?.closest('[data-index]')===node;})),true,'every unchanged floor center reaches its original real tile through the disposable cue');}
async function visualSample(page,at){return page.evaluate(at=>{const layer=document.querySelector('.idle-hint-layer');if(!layer)return null;for(const animation of layer.getAnimations({subtree:true})){animation.pause();animation.currentTime=at;}const screen=document.querySelector('#board').getScreenCTM();return {mode:layer.dataset.idleHintMode,pointerEvents:getComputedStyle(layer).pointerEvents,stones:[...layer.querySelectorAll('.idle-hint-pair')].map(node=>{const gem=node.querySelector('.gem'),transform=getComputedStyle(gem||node).transform,matrix=transform==='none'?new DOMMatrix():new DOMMatrix(transform);return {index:Number(node.dataset.idleHintSource),rect:node.getBoundingClientRect().toJSON(),transform:getComputedStyle(gem||node).transform,scale:Math.hypot(matrix.a,matrix.b),dx:screen.a*matrix.e+screen.c*matrix.f,dy:screen.b*matrix.e+screen.d*matrix.f};}),sheens:[...layer.querySelectorAll('.idle-hint-pair .idle-hint-sheen')].map(node=>Number(getComputedStyle(node).opacity)),animations:layer.getAnimations({subtree:true}).filter(a=>a.effect.target.matches('.gem')&&a.effect.target.closest('.idle-hint-pair')).map(a=>({duration:a.effect.getTiming().duration,iterations:a.effect.getTiming().iterations,state:a.playState}))};},at);}
async function screenshot(page,name,boardOnly=false){const file=path.join(output,name+'.png');if(boardOnly)await page.locator('#board').screenshot({path:file,animations:'allow'});else await page.screenshot({path:file,animations:'allow'});return file;}
function changedPixels(a,b,boardBox,regions){const first=PNG.sync.read(fs.readFileSync(a)),second=PNG.sync.read(fs.readFileSync(b));assert.equal(first.width,second.width);assert.equal(first.height,second.height);let changed=0;for(let i=0;i<first.data.length;i+=4){const x=(i/4%first.width)/first.width*boardBox.width+boardBox.x,y=Math.floor(i/4/first.width)/first.height*boardBox.height+boardBox.y;if(!regions.some(r=>x>=r.x&&x<=r.x+r.width&&y>=r.y&&y<=r.y+r.height))continue;if(first.data[i]!==second.data[i]||first.data[i+1]!==second.data[i+1]||first.data[i+2]!==second.data[i+2])changed++;}return changed;}
