   const persisted=await stores(f.page);await advance(f.page,9999);assert.equal(await appearanceCount(f.page),0,'no early cue');await advance(f.page,1);const cue=await validCue(f.page);assert.equal(cue.repeated,false);assert.equal(cue.ordinal,1);
