   const startPng=await screenshot(f.page,'cue-start-'+width+'x'+height,true),quarter=await visualSample(f.page,225),peak=await visualSample(f.page,450),peakPng=await screenshot(f.page,'cue-peak-'+width+'x'+height,true),second=await visualSample(f.page,675),rest=await visualSample(f.page,900);
   assert.deepEqual(start.sheens,[0,0]);for(const opacity of peak.sheens)assert(Math.abs(opacity-.08)<.001,'cheap white sheen adds exact pair brightness without filter');assert.equal(peak.sheens.length,2);assert.deepEqual(rest.sheens,[0,0]);const shifts=start.stones.map((s,i)=>({dx:peak.stones[i].dx,dy:peak.stones[i].dy,first:Math.hypot(peak.stones[i].dx,peak.stones[i].dy),rest:Math.hypot(rest.stones[i].dx,rest.stones[i].dy),quarter:Math.hypot(quarter.stones[i].dx,quarter.stones[i].dy),second:Math.hypot(second.stones[i].dx,second.stones[i].dy),scale:peak.stones[i].scale,endScale:rest.stones[i].scale}));
   for(const shift of shifts){assert(Math.abs(shift.first-2.5)<.2,'reciprocal peak stays exactly 2.5 CSS pixels');assert(shift.rest<.1,'the 900ms pulse returns to its origin');assert(shift.quarter>0&&shift.quarter<2.5,'first half approaches the partner');assert(shift.second>0&&shift.second<2.5,'second half returns from the partner');assert(Math.abs(shift.quarter-shift.second)<.1,'the two halves form one reciprocal pulse');assert(Math.abs(shift.scale-1.07)<.001,'the pair scales to exactly1.07 at450ms');assert(Math.abs(shift.endScale-1)<.001,'the pair returns to base scale at900ms');}
   for(let i=0;i<2;i++){const toward={x:start.stones[1-i].rect.x-start.stones[i].rect.x,y:start.stones[1-i].rect.y-start.stones[i].rect.y};assert(shifts[i].dx*toward.x+shifts[i].dy*toward.y>0,'each decorative stone moves toward its suggested partner');}assert(Math.hypot(shifts[0].dx+shifts[1].dx,shifts[0].dy+shifts[1].dy)<.1,'the two displacements are reciprocal');
