  const f=await open();try{const before=await stores(f.page);await advance(f.page,10000);await validCue(f.page);assert.equal(await f.page.evaluate(()=>{const animations=document.querySelector('.idle-hint-layer').getAnimations({subtree:true});for(const a of animations)a.cancel();return {total:animations.length,pairs:animations.filter(a=>a.effect.target.matches('.gem')&&a.effect.target.closest('.idle-hint-pair')).length};}).then(row=>{assert(row.total>=4,'all pair/auxiliary motion and sheen native animations are cancelled');return row.pairs;}),2);await f.page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));assert.equal(await f.page.locator('.idle-hint-layer').count(),0);await advance(f.page,900);await passiveEqual(f.page,before,'native animation rejection');assert.equal(await f.page.locator('#board > [data-index] > .gem').evaluateAll(nodes=>nodes.every(node=>getComputedStyle(node).opacity==='1')),true,'cancel restores all real gems');}finally{await f.close();}
